def choose_move(observation):
    def pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return v[0], v[1]
        except:
            pass
        return default

    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def nearest(points, origin):
        best = None
        best_d = None
        for item in points or []:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan(p, origin)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    env = observation.get("environment_name", "resource_collection")
    role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if role == "evader":
            gw = observation.get("grid_width", 0)
            gh = observation.get("grid_height", 0)
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
            target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
            return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]
        return [clamp_step(sx, ox), clamp_step(sy, oy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        target = nearest(targets, (sx, sy))
        if target is None:
            target = nearest(observation.get("resources") or [], (sx, sy))
        if target is None:
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("items") or []
    target = nearest(resources, (sx, sy))
    if target is None:
        if role == "evader":
            gw = observation.get("grid_width", 0)
            gh = observation.get("grid_height", 0)
            target = max([(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)], key=lambda c: manhattan(c, (ox, oy)))
            return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]
        return [clamp_step(sx, ox), clamp_step(sy, oy)]

    return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

